                            selectedHasForEach={selectedHasForEach}
                        />
                        <ActionConversationSearchRow service={conversationSearchService} />
                    </Box>
                    {children}
                </Box>
            </MarkdownTypeaheadLayerProvider>
        </ResizablePopper>
    )
