        this.dispatchEvent(new Event(MARKDOWN_FOCUS_REQUESTED_EVENT))
    }

    readonly requestInsertion = (markdown: string) => new Promise<void>((resolve, reject) => {
        let handled = false
        const request: MarkdownInsertionRequest = {
            acknowledge: () => {
