                cursor: disabled ? 'default' : 'row-resize', flexShrink: 0, height: '3px',
                touchAction: 'none', width: '100%',
                '&:hover, &:focus-visible': { bgcolor: disabled ? 'divider' : 'primary.main' },
            }}
            tabIndex={disabled ? -1 : 0}
        />
    );
}

